#include <afterlight/physics.h>
#include <stdio.h>
#include <math.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"Interaction %d: %s\n",__LINE__,#x);return 1;}}while(0)
int main(void){af_scene *s=af_scene_create();af_object_id id=af_scene_add_object(s,"Crate","cube");af_collider c=af_collider_default();c.type=AF_COLLIDER_BOX;CHECK(af_scene_set_object_collider(s,id,c));af_rigid_body b=af_rigid_body_default();b.enabled=true;b.type=AF_BODY_DYNAMIC;b.gravity_scale=0;CHECK(af_scene_set_body(s,id,b));af_physics *p=af_physics_create();af_character character={.position={-.9f,0,0}};CHECK(af_physics_push_character(p,s,0,&character,af_character_config_default(),(af_vec3){2,0,0},120,1.f/60)==1);CHECK(af_physics_step(p,s,1.f/60)&&af_physics_get_state(p,id).velocity.x>0);af_vec3 center=af_physics_get_state(p,id).position;CHECK(af_physics_grab(p,s,id,center)&&af_physics_held(p)==id);CHECK(af_physics_move_grab(p,(af_vec3){0,2,0}));for(unsigned i=0;i<180;++i)CHECK(af_physics_step(p,s,1.f/60));CHECK(fabsf(af_physics_get_state(p,id).position.y-2)<.02f);CHECK(af_physics_release(p,s,(af_vec3){4,0,0})&&!af_physics_held(p)&&af_physics_get_state(p,id).velocity.x>3);CHECK(!af_physics_move_grab(p,(af_vec3){NAN,0,0}));af_scene_destroy(s);af_physics_reset(p);s=af_scene_create();af_object_id player=af_scene_add_object(s,"Player","__node");af_collider capsule=af_collider_default();capsule.type=AF_COLLIDER_CAPSULE;capsule.radius=.35f;capsule.half_height=.55f;CHECK(af_scene_set_object_collider(s,player,capsule));af_gameplay_component g=af_gameplay_component_default();g.player.enabled=true;CHECK(af_scene_set_object_gameplay(s,player,g));af_object_id falling=af_scene_add_object(s,"Falling box","cube");CHECK(af_scene_set_object_collider(s,falling,c));af_transform t=af_transform_identity();t.position.y=4;CHECK(af_scene_set_object_transform(s,falling,t));b.gravity_scale=1;CHECK(af_scene_set_body(s,falling,b));for(unsigned i=0;i<240;++i)CHECK(af_physics_step(p,s,1.f/60));CHECK(fabsf(af_physics_get_state(p,falling).position.y-1.4f)<.05f);af_physics_destroy(p);af_scene_destroy(s);puts("Interaction: force-limited capsule push, collidable spring hold and release/throw passed.");return 0;}
